args.command:
python3 - <<'PY'
import subprocess
exe = b'/workspace/dataset/test4_executable'

def run(arg):
    p = subprocess.run([exe, arg], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.returncode, p.stdout.decode('ascii', 'backslashreplace').splitlines(), p.stderr

def name_bytes(bs):
    return ' '.join(f'0x{b:02X}' for b in bs)

groups = {}
for b in list(range(1, 32)) + [127]:
    for template in (bytes([b]), b'a' + bytes([b]) + b'b.com'):
        rc, out, err = run(template)
        groups.setdefault((rc, tuple(out), err), []).append(name_bytes(template))
for key, vals in groups.items():
    rc, out, err = key
    print(f'RESULT rc={rc} stdout={out!r} stderr={err!r}')
    print('  ' + '; '.join(vals))
PY

