my $exe = "/workspace/dataset/test4_executable";
my %groups;
for my $b (1..31,127) {
  for my $arg (chr($b), "a".chr($b)."b.com") {
    open my $fh, "-|", $exe, $arg or die $!;
    my @out = map { chomp; $_ } <$fh>;
    close $fh;
    my $key = join("|", @out);
    push @{$groups{$key}}, join(" ", map { sprintf "0x%02X", ord } split //, $arg);
  }
}
for my $key (sort keys %groups) {
  print "RESULT [$key]\n";
  print "  ", join("; ", @{$groups{$key}}), "\n";
}
'

