args.content:
//! Byte-level re-implementation of the `idna` namespace functions used by
//! `test4.cpp`, matching the observed behavior of the C++ binary exactly:
//!
//! - `is_valid_domain`: 1 <= byte length <= 255, content unrestricted
//!   (no per-label, dot-position, or character-class checks).
//! - `is_valid_label`: 1 <= byte length <= 63, applied to the whole string
//!   (dots are not treated as separators).
//! - `is_ascii_domain`: every byte < 0x80 (vacuously true for empty input).
//! - `is_idn_domain`: at least one byte >= 0x80 (exact complement of the
//!   ASCII check; punycode `xn--` labels are pure ASCII and not IDN).

/// Returns true if the domain is non-empty and at most 255 bytes long.
pub fn is_valid_domain(domain: &[u8]) -> bool {
    !domain.is_empty() && domain.len() <= 255
}

/// Returns true if the label is non-empty and at most 63 bytes long.
pub fn is_valid_label(label: &[u8]) -> bool {
    !label.is_empty() && label.len() <= 63
}

/// Returns true if every byte is ASCII (< 0x80). True for empty input.
pub fn is_ascii_domain(domain: &[u8]) -> bool {
    domain.iter().all(|&b| b < 0x80)
}

/// Returns true if any byte is non-ASCII (>= 0x80).
pub fn is_idn_domain(domain: &[u8]) -> bool {
    domain.iter().any(|&b| b >= 0x80)
}

